      "usable": true
    },
    {
      "passage": 6,
      "question": "What is the average velocity shown on the constant acceleration velocity-versus-time graph?",
      "reference": "The average velocity is $\\frac{1}{2}(v_0 + v) = 60 \\text{ km/h}$.",
      "usable": true
    },
    {
