    },
    {
      "passage": 8,
      "question": "What parameters are used to calculate the ideal speed for a car on a frictionless steeply banked curve?",
      "reference": "To illustrate, calculate the speed at which a $100.0\\text{-m}$ radius curve banked at $31.0^\\circ$ should be driven if the road were frictionless.",
      "usable": true
    },
    {
      "passage": 9,
      "question": "What starting height is required for a toy car to successfully complete a frictionless loop-the-loop?",
      "reference": "How high, measured from the bottom of the loop, must the car be placed to start from rest on the approaching section of track and go all the way around the loop?",
      "usable": true
    },
    {
      "passage": 10,
      "question": "How is instantaneous velocity defined mathematically in relation to the position function?",
      "reference": "The instantaneous velocity of an object is the limit of the average velocity as the elapsed time approaches zero, or the derivative of $x$ with respect to $t$: $v(t) = \\frac{d}{dt}x(t)$.",
      "usable": true
    }
  ]
}

